SELECT r.rolname,x.privilege,NOT has_sequence_privilege(r.oid,c.oid,x.privilege) AS denied,NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(c.relacl,acldefault('S',c.relowner))) a WHERE a.grantee=0) AS public_absent FROM pg_class c CROSS JOIN pg_roles r CROSS JOIN unnest(ARRAY['SELECT','USAGE','UPDATE']) x(privilege) WHERE c.oid=pg_get_serial_sequence('public.training_sessions','id')::regclass AND r.rolname IN ('anon','authenticated') ORDER BY r.rolname,x.privilege;
